1	interface QuoteStep {
2	  op: "quote";
3	  items: { type: string }[];
4	}
5	
6	interface Scenario {
7	  customer: { yearsWithMHPCO: number };
8	  steps: QuoteStep[];
9	}
10	
11	const BASE_PREMIUM: Record<string, number> = {
12	  sword: 100,
13	  amulet: 60,
14	  staff: 80,
15	};
16	
17	const PROCESSING_FEE = 5;
18	const FIRST_INSURANCE_SURCHARGE = 0.1;
19	
20	const itemPremium = (item: { type: string }): number => {
21	  const base = BASE_PREMIUM[item.type];
22	  return base + base * FIRST_INSURANCE_SURCHARGE;
23	};
24	
25	const quotePremium = (items: { type: string }[]): number => {
26	  const itemsTotal = items.reduce((sum, item) => sum + itemPremium(item), 0);
27	  return Math.ceil(itemsTotal + PROCESSING_FEE);
28	};
29	
30	export const runScenario = (scenario: Scenario): { results: unknown[] } => {
31	  const results = scenario.steps.map((step) => ({
32	    premium: quotePremium(step.items),
33	  }));
34	  return { results };
35	};
